s<-enc2utf8("éaβ")
stopifnot(identical(grepl("\\w",c("é","a","β"),perl=TRUE),c(FALSE,TRUE,FALSE)))
stopifnot(identical(grepl("(*UCP)\\w",c("é","a","β"),perl=TRUE),c(TRUE,TRUE,TRUE)))
stopifnot(identical(grep("\\w",c("é","a","β"),perl=TRUE),2L))
stopifnot(identical(gsub("\\w","X",s,perl=TRUE),enc2utf8("éXβ")))
stopifnot(identical(gsub("\\W","X",s,perl=TRUE),"XaX"))
stopifnot(identical(gsub("(*UCP)\\w","X",s,perl=TRUE),"XXX"))
stopifnot(identical(sub("(*UCP)(?<letter>\\w)\\k<letter>","\\1",enc2utf8("aa-éé"),perl=TRUE),enc2utf8("a-éé")))
stopifnot(identical(gsub("(*UCP)(?<letter>\\w)\\k<letter>","\\1",enc2utf8("aa-éé"),perl=TRUE),enc2utf8("a-é")))
stopifnot(identical(strsplit(s,"\\w",perl=TRUE)[[1L]],enc2utf8(c("é","β"))))
stopifnot(identical(strsplit(s,"(*UCP)\\w",perl=TRUE)[[1L]],c("","","")))
r<-regexpr("(?<word>\\w+)",s,perl=TRUE)
stopifnot(identical(as.integer(r),2L),identical(as.integer(attr(r,"match.length")),1L),identical(attr(r,"capture.names"),"word"),identical(as.integer(attr(r,"capture.start")),2L))
r<-regexpr("(*UCP)(?<word>\\w+)",s,perl=TRUE)
stopifnot(identical(as.integer(r),1L),identical(as.integer(attr(r,"match.length")),3L),identical(attr(r,"capture.names"),"word"),identical(as.integer(attr(r,"capture.start")),1L))
g<-gregexpr("(*UCP)(?<word>\\w+)",enc2utf8("éa-β"),perl=TRUE)[[1L]]
stopifnot(identical(as.integer(g),c(1L,4L)),identical(as.integer(attr(g,"match.length")),c(2L,1L)),identical(as.integer(attr(g,"capture.start")),c(1L,4L)),identical(as.integer(attr(g,"capture.length")),c(2L,1L)))
e<-regexec("(*UCP)(?<word>\\w+)",s,perl=TRUE)[[1L]]
stopifnot(identical(as.integer(e),c(1L,1L)),identical(as.integer(attr(e,"match.length")),c(3L,3L)))
stopifnot(identical(gsub("\\b","|",enc2utf8("éa"),perl=TRUE),enc2utf8("é|a|")))
stopifnot(identical(gsub("(*UCP)\\b","|",enc2utf8("éa"),perl=TRUE),enc2utf8("|éa|")))
stopifnot(identical(as.integer(regexpr("\\b",enc2utf8("éa"),perl=TRUE)),2L))
stopifnot(identical(as.integer(regexpr("(*UCP)\\b",enc2utf8("éa"),perl=TRUE)),1L))
stopifnot(identical(as.integer(gregexpr("\\b",enc2utf8("éa"),perl=TRUE)[[1L]]),2L))
stopifnot(identical(grepl("(?xx)^[ a]$",c(" ","a"),perl=TRUE),c(FALSE,TRUE)))
stopifnot(identical(grepl("(?x)^[ a]$",c(" ","a"),perl=TRUE),c(TRUE,TRUE)))
stopifnot(identical(grepl("(*UCP)(?aW)^\\w$",enc2utf8(c("é","a")),perl=TRUE),c(FALSE,TRUE)))
stopifnot(identical(grepl("(*UTF)(*UCP)^\\w$",enc2utf8(c("é","a")),perl=TRUE),c(TRUE,TRUE)))
stopifnot(grepl("(*UCP)^\\w$",intToUtf8(2191L),perl=TRUE),grepl("^\\p{L}$",intToUtf8(2191L),perl=TRUE))
TRUE
